+package s2
+
+import (
+	"errors"
+	"fmt"
+	"io"
+	"math"
+	"sort"
+	"sync/atomic"
+)
+
+// The ShapeIndex encoding stores the shapes together with the complete cell
+// structure of the index so that a decoded index can be queried immediately
+// without being rebuilt. The layout is:
+//
+//	uint8    shapeIndexEncodingVersion
+//	uvarint  maxEdgesPerCell
+//	uvarint  nextID
+//	uvarint  number of shapes
+//	  per shape (in increasing order of shape ID):
+//	    uvarint  shape ID
+//	    uint8    shape kind
+//	    ...      kind specific payload
+//	uvarint  number of cells
+//	  per cell (in increasing CellID order):
+//	    uvarint  CellID delta from the previous cell (the first is absolute)
+//	    uvarint  number of clipped shapes
+//	      per clipped shape (in increasing order of shape ID):
+//	        uvarint  shape ID
+//	        bool     containsCenter
+//	        uvarint  number of edges
+//	        uvarint  edge IDs
+//
+// All multi-byte fixed width values are little endian.
+
+const shapeIndexEncodingVersion uint8 = 1
+
+// shapeKind identifies the concrete type of an encoded shape.
+type shapeKind uint8
+
+const (
+	shapeKindPolygon shapeKind = iota + 1
+	shapeKindLoop
+	shapeKindPolyline
+	shapeKindPointVector
+	shapeKindLaxPolyline
+	shapeKindLaxLoop
+	shapeKindLaxPolygon
+	// shapeKindGeneric is used for any other Shape. Such shapes are decoded
+	// as an encodedShape holding the same edges, chains and properties.
+	shapeKindGeneric
+)
+
+const (
+	// maxEncodedMaxEdgesPerCell guards against absurd maxEdgesPerCell values.
+	maxEncodedMaxEdgesPerCell = 1 << 30
+	// maxEncodedEdges bounds the number of edges in a generic shape.
+	maxEncodedEdges = maxEncodedVertices
+	// decodeChunk is the largest number of elements preallocated at once
+	// while decoding. Larger slices are grown as data is actually read, so
+	// that a corrupt length prefix cannot force a huge allocation.
+	decodeChunk = 1024
+)
+
+var errShapeIndexTruncated = errors.New("s2: truncated ShapeIndex encoding")
+
+// Encode encodes the ShapeIndex, including all of its shapes and its cell
+// structure. Any pending updates are applied first, so an index does not
+// need to be explicitly built before it is encoded. Shape IDs are preserved.
+func (s *ShapeIndex) Encode(w io.Writer) error {
+	s.maybeApplyUpdates()
+	s.mu.RLock()
+	defer s.mu.RUnlock()
+
+	e := &encoder{w: w}
+	s.encode(e)
+	return e.err
+}
+
+func (s *ShapeIndex) encode(e *encoder) {
+	e.writeUint8(shapeIndexEncodingVersion)
+	e.writeUvarint(uint64(s.maxEdgesPerCell))
+	e.writeUvarint(uint64(s.nextID))
+
+	ids := make([]int32, 0, len(s.shapes))
+	for id := range s.shapes {
+		ids = append(ids, id)
+	}
+	sort.Slice(ids, func(i, j int) bool { return ids[i] < ids[j] })
+
+	e.writeUvarint(uint64(len(ids)))
+	for _, id := range ids {
+		if e.err != nil {
+			return
+		}
+		e.writeUvarint(uint64(id))
+		encodeShape(e, s.shapes[id])
+	}
+
+	e.writeUvarint(uint64(len(s.cells)))
+	var prev CellID
+	for _, cellID := range s.cells {
+		if e.err != nil {
+			return
+		}
+		e.writeUvarint(uint64(cellID - prev))
+		prev = cellID
+
+		clippedShapes := liveClippedShapes(s.cellMap[cellID], s.shapes)
+		e.writeUvarint(uint64(len(clippedShapes)))
+		for _, clipped := range clippedShapes {
+			e.writeUvarint(uint64(clipped.shapeID))
+			e.writeBool(clipped.containsCenter)
+			e.writeUvarint(uint64(len(clipped.edges)))
+			for _, edge := range clipped.edges {
+				e.writeUvarint(uint64(edge))
+			}
+		}
+	}
+}
+
+// liveClippedShapes returns the clipped shapes of the given cell that belong
+// to shapes still present in the index. Removed shapes may still be referenced
+// by index cells, and those stale references are not encoded.
+func liveClippedShapes(cell *ShapeIndexCell, shapes map[int32]Shape) []*clippedShape {
+	live := make([]*clippedShape, 0, len(cell.shapes))
+	for _, clipped := range cell.shapes {
+		if shapes[clipped.shapeID] != nil {
+			live = append(live, clipped)
+		}
+	}
+	return live
+}
+
+// Decode decodes a ShapeIndex previously written by Encode, replacing the
+// current contents of s. The decoded index is ready for use without Build.
+// Malformed input results in an error and leaves s unchanged.
+func (s *ShapeIndex) Decode(r io.Reader) (err error) {
+	defer func() {
+		// The decoder validates its input, but this is a last line of
+		// defense so that malformed input never crashes the caller.
+		if p := recover(); p != nil {
+			err = fmt.Errorf("s2: malformed ShapeIndex encoding: %v", p)
+		}
+	}()
+
+	d := &decoder{r: asByteReader(r)}
+	decoded := decodeShapeIndex(d)
+	if d.err != nil {
+		if d.err == io.EOF || d.err == io.ErrUnexpectedEOF {
+			return errShapeIndexTruncated
+		}
+		return d.err
+	}
+
+	s.mu.Lock()
+	s.maxEdgesPerCell = decoded.maxEdgesPerCell
+	s.shapes = decoded.shapes
+	s.nextID = decoded.nextID
+	s.cellMap = decoded.cellMap
+	s.cells = decoded.cells
+	s.pendingAdditionsPos = decoded.nextID
+	s.pendingRemovals = nil
+	atomic.StoreInt32(&s.status, fresh)
+	s.mu.Unlock()
+	return nil
+}
+
+func decodeShapeIndex(d *decoder) *ShapeIndex {
+	s := NewShapeIndex()
+
+	if version := d.readUint8(); d.err == nil && version != shapeIndexEncodingVersion {
+		d.err = fmt.Errorf("s2: unsupported ShapeIndex encoding version %d", version)
+	}
+	s.maxEdgesPerCell = int(readCount(d, maxEncodedMaxEdgesPerCell, "maxEdgesPerCell"))
+	s.nextID = int32(readCount(d, math.MaxInt32, "next shape ID"))
+	numShapes := readCount(d, uint64(s.nextID), "shapes")
+
+	prevID := int32(-1)
+	for i := uint64(0); i < numShapes && d.err == nil; i++ {
+		id := int32(readCount(d, math.MaxInt32, "shape ID"))
+		if d.err != nil {
+			break
+		}
+		if id <= prevID || id >= s.nextID {
+			d.err = fmt.Errorf("s2: invalid shape ID %d", id)
+			break
+		}
+		prevID = id
+		shape := decodeShape(d)
+		if d.err != nil {
+			break
+		}
+		s.shapes[id] = shape
+	}
+
+	numCells := readCount(d, math.MaxInt64, "cells")
+	var prev CellID
+	for i := uint64(0); i < numCells && d.err == nil; i++ {
+		delta := d.readUvarint()
+		if d.err != nil {
+			break
+		}
+		cellID := prev + CellID(delta)
+		if !cellID.IsValid() || cellID < prev || (i > 0 && cellID.RangeMin() <= prev.RangeMax()) {
+			d.err = fmt.Errorf("s2: invalid or out of order cell %v", cellID)
+			break
+		}
+		prev = cellID
+
+		cell := decodeShapeIndexCell(d, s.shapes)
+		if d.err != nil {
+			break
+		}
+		s.cells = append(s.cells, cellID)
+		s.cellMap[cellID] = cell
+	}
+	return s
+}
+
+func decodeShapeIndexCell(d *decoder, shapes map[int32]Shape) *ShapeIndexCell {
+	numClipped := readCount(d, uint64(len(shapes)), "clipped shapes")
+	cell := &ShapeIndexCell{shapes: make([]*clippedShape, 0, min(numClipped, decodeChunk))}
+
+	prevID := int32(-1)
+	for j := uint64(0); j < numClipped && d.err == nil; j++ {
+		id := int32(readCount(d, math.MaxInt32, "shape ID"))
+		containsCenter := d.readBool()
+		if d.err != nil {
+			break
+		}
+		shape, ok := shapes[id]
+		if !ok || id <= prevID {
+			d.err = fmt.Errorf("s2: invalid clipped shape ID %d", id)
+			break
+		}
+		prevID = id
+
+		numShapeEdges := uint64(shape.NumEdges())
+		numEdges := readCount(d, numShapeEdges, "clipped edges")
+		clipped := &clippedShape{
+			shapeID:        id,
+			containsCenter: containsCenter,
+			edges:          make([]int, 0, min(numEdges, decodeChunk)),
+		}
+		for k := uint64(0); k < numEdges && d.err == nil; k++ {
+			edge := readCount(d, numShapeEdges-1, "edge ID")
+			clipped.edges = append(clipped.edges, int(edge))
+		}
+		cell.shapes = append(cell.shapes, clipped)
+	}
+	return cell
+}
+
+// readCount reads a uvarint and sets an error if it exceeds limit.
+func readCount(d *decoder, limit uint64, what string) uint64 {
+	x := d.readUvarint()
+	if d.err == nil && x > limit {
+		d.err = fmt.Errorf("s2: %s value %d exceeds limit %d", what, x, limit)
+	}
+	if d.err != nil {
+		return 0
+	}
+	return x
+}
+
+func encodeShape(e *encoder, shape Shape) {
+	switch sh := shape.(type) {
+	case *Polygon:
+		e.writeUint8(uint8(shapeKindPolygon))
+		e.writeBool(sh.hasHoles)
+		e.writeUvarint(uint64(len(sh.loops)))
+		for _, l := range sh.loops {
+			encodeLoopState(e, l)
+		}
+		encodeRect(e, sh.bound)
+	case *Loop:
+		e.writeUint8(uint8(shapeKindLoop))
+		encodeLoopState(e, sh)
+	case *Polyline:
+		e.writeUint8(uint8(shapeKindPolyline))
+		encodePoints(e, *sh)
+	case *PointVector:
+		e.writeUint8(uint8(shapeKindPointVector))
+		encodePoints(e, *sh)
+	case *LaxPolyline:
+		e.writeUint8(uint8(shapeKindLaxPolyline))
+		encodePoints(e, sh.vertices)
+	case *LaxLoop:
+		e.writeUint8(uint8(shapeKindLaxLoop))
+		encodePoints(e, sh.vertices[:sh.numVertices])
+	case *LaxPolygon:
+		e.writeUint8(uint8(shapeKindLaxPolygon))
+		e.writeUvarint(uint64(sh.numLoops))
+		for i := 0; i < sh.numLoops; i++ {
+			n := sh.numLoopVertices(i)
+			e.writeUvarint(uint64(n))
+			for j := 0; j < n; j++ {
+				encodePoint(e, sh.loopVertex(i, j))
+			}
+		}
+	case nil:
+		if e.err == nil {
+			e.err = errors.New("s2: cannot encode a nil Shape")
+		}
+	default:
+		e.writeUint8(uint8(shapeKindGeneric))
+		encodeGenericShape(e, shape)
+	}
+}
+
+func decodeShape(d *decoder) Shape {
+	kind := shapeKind(d.readUint8())
+	if d.err != nil {
+		return nil
+	}
+	switch kind {
+	case shapeKindPolygon:
+		p := &Polygon{}
+		p.hasHoles = d.readBool()
+		numLoops := readCount(d, maxEncodedLoops, "loops")
+		p.loops = make([]*Loop, 0, min(numLoops, decodeChunk))
+		for i := uint64(0); i < numLoops && d.err == nil; i++ {
+			l := decodeLoopState(d)
+			p.loops = append(p.loops, l)
+			p.numVertices += len(l.vertices)
+		}
+		p.bound = decodeRect(d)
+		if d.err != nil {
+			return nil
+		}
+		p.subregionBound = ExpandForSubregions(p.bound)
+		p.initEdgesAndIndex()
+		return p
+	case shapeKindLoop:
+		l := decodeLoopState(d)
+		if d.err != nil {
+			return nil
+		}
+		return l
+	case shapeKindPolyline:
+		p := Polyline(decodePoints(d))
+		return &p
+	case shapeKindPointVector:
+		p := PointVector(decodePoints(d))
+		return &p
+	case shapeKindLaxPolyline:
+		return &LaxPolyline{vertices: decodePoints(d)}
+	case shapeKindLaxLoop:
+		pts := decodePoints(d)
+		return &LaxLoop{numVertices: len(pts), vertices: pts}
+	case shapeKindLaxPolygon:
+		numLoops := readCount(d, maxEncodedLoops, "loops")
+		loops := make([][]Point, 0, min(numLoops, decodeChunk))
+		for i := uint64(0); i < numLoops && d.err == nil; i++ {
+			loops = append(loops, decodePoints(d))
+		}
+		if d.err != nil {
+			return nil
+		}
+		return LaxPolygonFromPoints(loops)
+	case shapeKindGeneric:
+		return decodeGenericShape(d)
+	}
+	d.err = fmt.Errorf("s2: unknown encoded shape kind %d", kind)
+	return nil
+}
+
+func encodePoint(e *encoder, p Point) {
+	e.writeFloat64(p.X)
+	e.writeFloat64(p.Y)
+	e.writeFloat64(p.Z)
+}
+
+func decodePoint(d *decoder) Point {
+	var p Point
+	p.X = d.readFloat64()
+	p.Y = d.readFloat64()
+	p.Z = d.readFloat64()
+	return p
+}
+
+func encodePoints(e *encoder, pts []Point) {
+	e.writeUvarint(uint64(len(pts)))
+	for _, p := range pts {
+		encodePoint(e, p)
+	}
+}
+
+// decodePoints reads a length prefixed list of points. The result is grown
+// as points are read so a corrupt length cannot force a huge allocation.
+func decodePoints(d *decoder) []Point {
+	n := readCount(d, maxEncodedVertices, "vertices")
+	pts := make([]Point, 0, min(n, decodeChunk))
+	for i := uint64(0); i < n && d.err == nil; i++ {
+		pts = append(pts, decodePoint(d))
+	}
+	return pts
+}
+
+func encodeRect(e *encoder, r Rect) {
+	e.writeFloat64(r.Lat.Lo)
+	e.writeFloat64(r.Lat.Hi)
+	e.writeFloat64(r.Lng.Lo)
+	e.writeFloat64(r.Lng.Hi)
+}
+
+func decodeRect(d *decoder) Rect {
+	var r Rect
+	r.Lat.Lo = d.readFloat64()
+	r.Lat.Hi = d.readFloat64()
+	r.Lng.Lo = d.readFloat64()
+	r.Lng.Hi = d.readFloat64()
+	return r
+}
+
+// encodeLoopState writes the full internal state of a Loop so that it can be
+// restored exactly, preserving vertex order and therefore edge IDs.
+func encodeLoopState(e *encoder, l *Loop) {
+	encodePoints(e, l.vertices)
+	e.writeBool(l.originInside)
+	e.writeUvarint(uint64(max(l.depth, 0)))
+	encodeRect(e, l.bound)
+}
+
+func decodeLoopState(d *decoder) *Loop {
+	l := &Loop{}
+	l.vertices = decodePoints(d)
+	l.originInside = d.readBool()
+	l.depth = int(readCount(d, maxEncodedLoops, "loop depth"))
+	l.bound = decodeRect(d)
+	l.subregionBound = ExpandForSubregions(l.bound)
+	l.index = NewShapeIndex()
+	l.index.Add(l)
+	return l
+}
+
+// encodedShape is a generic Shape restored from an encoding of a Shape type
+// that has no dedicated encoding.
+type encodedShape struct {
+	dimension int
+	refPoint  ReferencePoint
+	edges     []Edge
+	chains    []Chain
+}
+
+func (s *encodedShape) NumEdges() int                  { return len(s.edges) }
+func (s *encodedShape) Edge(i int) Edge                { return s.edges[i] }
+func (s *encodedShape) ReferencePoint() ReferencePoint { return s.refPoint }
+func (s *encodedShape) NumChains() int                 { return len(s.chains) }
+func (s *encodedShape) Chain(i int) Chain              { return s.chains[i] }
+func (s *encodedShape) ChainEdge(i, j int) Edge        { return s.edges[s.chains[i].Start+j] }
+func (s *encodedShape) Dimension() int                 { return s.dimension }
+func (s *encodedShape) IsEmpty() bool                  { return defaultShapeIsEmpty(s) }
+func (s *encodedShape) IsFull() bool                   { return defaultShapeIsFull(s) }
+func (s *encodedShape) typeTag() typeTag               { return typeTagNone }
+func (s *encodedShape) privateInterface()              {}
+
+func (s *encodedShape) ChainPosition(e int) ChainPosition {
+	// Find the last chain starting at or before e.
+	i := sort.Search(len(s.chains), func(i int) bool { return s.chains[i].Start > e }) - 1
+	for i > 0 && s.chains[i].Length == 0 {
+		i--
+	}
+	if i < 0 {
+		return ChainPosition{0, e}
+	}
+	return ChainPosition{i, e - s.chains[i].Start}
+}
+
+func encodeGenericShape(e *encoder, s Shape) {
+	e.writeUvarint(uint64(s.Dimension()))
+	ref := s.ReferencePoint()
+	encodePoint(e, ref.Point)
+	e.writeBool(ref.Contained)
+
+	numEdges := s.NumEdges()
+	e.writeUvarint(uint64(numEdges))
+	for i := 0; i < numEdges; i++ {
+		edge := s.Edge(i)
+		encodePoint(e, edge.V0)
+		encodePoint(e, edge.V1)
+	}
+	numChains := s.NumChains()
+	e.writeUvarint(uint64(numChains))
+	for i := 0; i < numChains; i++ {
+		c := s.Chain(i)
+		e.writeUvarint(uint64(c.Start))
+		e.writeUvarint(uint64(c.Length))
+	}
+}
+
+func decodeGenericShape(d *decoder) Shape {
+	s := &encodedShape{}
+	s.dimension = int(readCount(d, 2, "dimension"))
+	s.refPoint.Point = decodePoint(d)
+	s.refPoint.Contained = d.readBool()
+
+	numEdges := readCount(d, maxEncodedEdges, "edges")
+	s.edges = make([]Edge, 0, min(numEdges, decodeChunk))
+	for i := uint64(0); i < numEdges && d.err == nil; i++ {
+		v0 := decodePoint(d)
+		v1 := decodePoint(d)
+		s.edges = append(s.edges, Edge{v0, v1})
+	}
+
+	numChains := readCount(d, maxEncodedEdges, "chains")
+	s.chains = make([]Chain, 0, min(numChains, decodeChunk))
+	next := uint64(0)
+	for i := uint64(0); i < numChains && d.err == nil; i++ {
+		start := readCount(d, numEdges, "chain start")
+		length := readCount(d, numEdges, "chain length")
+		if d.err != nil {
+			break
+		}
+		if start < next || start+length > numEdges {
+			d.err = fmt.Errorf("s2: invalid chain (%d, %d)", start, length)
+			break
+		}
+		next = start + length
+		s.chains = append(s.chains, Chain{int(start), int(length)})
+	}
+	if d.err != nil {
+		return nil
+	}
+	return s
+}
