+func shapeIndexRoundTrip(t *testing.T, index *ShapeIndex) *ShapeIndex {
+	t.Helper()
+	var buf bytes.Buffer
+	if err := index.Encode(&buf); err != nil {
+		t.Fatalf("Encode() = %v", err)
+	}
+	if buf.Len() == 0 {
+		t.Fatalf("Encode() produced no bytes")
+	}
+	got := NewShapeIndex()
+	if err := got.Decode(&buf); err != nil {
+		t.Fatalf("Decode() = %v", err)
+	}
+	return got
+}
+
+func checkShapeIndexEqual(t *testing.T, got, want *ShapeIndex) {
+	t.Helper()
+	want.Build()
+	if !got.IsFresh() {
+		t.Errorf("decoded index is not fresh")
+	}
+	if got.Len() != want.Len() || got.nextID != want.nextID {
+		t.Fatalf("Len, nextID = %d, %d, want %d, %d", got.Len(), got.nextID, want.Len(), want.nextID)
+	}
+	if got.maxEdgesPerCell != want.maxEdgesPerCell {
+		t.Errorf("maxEdgesPerCell = %d, want %d", got.maxEdgesPerCell, want.maxEdgesPerCell)
+	}
+	for id, ws := range want.shapes {
+		gs := got.Shape(id)
+		if gs == nil {
+			t.Fatalf("shape %d missing", id)
+		}
+		if _, ok := gs.(*encodedShape); ok {
+			if _, ok := ws.(*edgeVectorShape); !ok {
+				t.Errorf("shape %d type = %T, want %T", id, gs, ws)
+			}
+		} else if reflect.TypeOf(gs) != reflect.TypeOf(ws) {
+			t.Errorf("shape %d type = %T, want %T", id, gs, ws)
